template <typename T>
class MyVector {
private:
    T* data;
    size_t sz;
    size_t cap;

public:
    MyVector() : data(nullptr), sz(0), cap(0) {}

    ~MyVector() { delete[] data; }

    void push_back(const T& val) {
        if (sz == cap) {
            cap = (cap == 0) ? 1 : cap * 2;
            T* new_data = new T[cap];
            for (size_t i = 0; i < sz; i++) {
                new_data[i] = std::move(data[i]);
            }
            delete[] data;
            data = new_data;
        }
        data[sz++] = val;
    }

    T& operator[](size_t index) { return data[index]; }
};
